<?php declare(strict_types=1); namespace Annam; $title='Billing settings';$subtitle='Save your business details once. Future bills use these settings; existing bills stay unchanged.'; ?>
<form class="o-form" method="post"><?= csrf() ?><input type="hidden" name="number_format" value="<?= e($profile['number_format']) ?>"><input type="hidden" name="bill_timing" value="<?= e(empty($billingPortal)?$profile['bill_timing']:'on_payment') ?>"><section class="o-card"><p>Choose your GST status, rate and SAC / HSN as confirmed by your accountant. No tax is collected for unregistered or composition businesses. Inclusive prices should match the amount customers pay.</p><div class="o-grid-form"><?php foreach(['legal_name'=>'Legal name','address'=>'Address','state'=>'State','state_code'=>'State code','fssai_no'=>'FSSAI number','invoice_prefix'=>'Invoice prefix','gst_mode'=>'GST mode','gstin'=>'GSTIN','tax_rate'=>'Tax rate (%)','sac'=>'SAC / HSN'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><?php if($key==='gst_mode'): ?><select class="o-input" name="gst_mode"><?php foreach(['regular'=>'Regular','composition'=>'Composition','unregistered'=>'Unregistered'] as $v=>$text): ?><option value="<?= e($v) ?>" <?= $profile[$key]===$v?'selected':'' ?>><?= e($text) ?></option><?php endforeach; ?></select><?php elseif($key==='address'): ?><textarea class="o-input" name="address"><?= e($profile[$key]) ?></textarea><?php else: ?><input class="o-input" name="<?= e($key) ?>" value="<?= e($profile[$key]) ?>" <?= in_array($key,['legal_name','state','state_code','fssai_no','invoice_prefix'],true)?'required':'' ?>><?php endif; ?></label><?php endforeach; ?><?php foreach(['prices_include_tax'=>'Prices include tax','round_total'=>'Round total to nearest rupee','delivery_fee_taxable'=>'Apply GST to delivery fee'] as $key=>$label): ?><label class="o-check"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= $profile[$key]?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b><?= e($label) ?></b></label><?php endforeach; ?><label class="o-field o-field-wide"><span>Footer</span><textarea class="o-input" name="footer"><?= e($profile['footer']) ?></textarea></label></div></section><button class="o-btn o-btn-primary">Save billing settings</button></form>
